parameters.jsCode:
const policy = $('Set GDPR Policy').first().json;
let src;
try { src = $('Mark Form Entry').first().json; } catch (e) { src = $('Mark Sub-Workflow Entry').first().json; }
const raw = String(src.subject_identifier || '').trim().toLowerCase();
const minLen = Number(policy.min_identifier_length) || 6;
const usable = raw.length >= minLen;
return [{ json: {
  entry: String(src.entry || 'subworkflow'),
  request_type: String(src.request_type || 'Access'),
  subject_identifier: raw,
  identifier_usable: usable,
  search_key: usable ? raw : '__refused_no_usable_identifier__',
  guard_note: usable ? '' : 'The identifier is empty or shorter than ' + minLen + ' characters. Searching on it would match unrelated people, so nothing was searched.'
} }];

const crypto = require('crypto');
const guard = $('Check The Identifier Is Usable').first().json;
const key = String(guard.search_key || '');
const now = new Date().toISOString();
const hash = crypto.createHash('sha256').update(key).digest('hex');
const caseId = 'DSR-' + hash.slice(0, 8).toUpperCase();
const systems = [
  { label: 'Demo CRM contacts', nodeName: 'Search Demo CRM Contacts' },
  { label: 'Demo support tickets', nodeName: 'Search Demo Support Tickets' },
  { label: 'Demo mailing list', nodeName: 'Search Demo Mailing List' }
];
const out = [];
for (const sys of systems) {
  let items = null;
  let failed = false;
  let detail = '';
  try { items = $(sys.nodeName).all(); } catch (e) { failed = true; detail = 'The search step did not run: ' + String(e.message).slice(0, 160); }
  if (!failed && Array.isArray(items)) {
    for (const it of items) {
      if (it && it.json && it.json.error) { failed = true; detail = 'The system returned an error: ' + String(it.json.error).slice(0, 160); }
    }
  }
  let found = 0;
  const refs = [];
  if (!failed && Array.isArray(items)) {
    for (const it of items) {
      const row = (it && it.json) || {};
      if (row.email && String(row.email).trim().toLowerCase() === key) {
        found = found + 1;
        if (row.record_ref) { refs.push(String(row.record_ref)); }
      }
    }
  }
  const notSearched = guard.identifier_usable !== true;
  out.push({ json: {
    case_id: caseId,
    subject_hash: hash,
    system_name: sys.label,
    searched_at: now,
    records_found: (failed || notSearched) ? 0 : found,
    status: notSearched ? 'NOT_SEARCHED' : (failed ? 'FAILED' : 'ANSWERED'),
    detail: notSearched ? 'Not searched: the request carried no usable identifier' : (failed ? detail : (found > 0 ? 'Matched records: ' + refs.join(', ') : 'Answered, held no matching record')),
    search_key: key,
    identifier_usable: guard.identifier_usable === true,
    request_type: guard.request_type,
    entry: guard.entry
  } });
}
return out;

const rows = $('Collect Findings Per System').all().map(i => i.json);
const policy = $('Set GDPR Policy').first().json;
const guard = $('Check The Identifier Is Usable').first().json;
const first = rows[0] || {};
let answered = 0;
let failed = 0;
let notSearched = 0;
let total = 0;
const lines = [];
for (const r of rows) {
  if (r.status === 'ANSWERED') { answered = answered + 1; }
  else if (r.status === 'FAILED') { failed = failed + 1; }
  else { notSearched = notSearched + 1; }
  total = total + Number(r.records_found || 0);
  lines.push(r.system_name + ' - ' + r.status + ' - ' + r.records_found + ' record(s) - ' + r.detail);
}
const days = Number(policy.response_days) || 30;
const now = new Date();
const due = new Date(now.getTime() + days * 86400000);
let verdict = '';
let note = '';
if (guard.identifier_usable !== true) {
  verdict = 'NOT_SEARCHED';
  note = String(guard.guard_note || 'No usable identifier was supplied, so no system was searched.') + ' This is a problem with the request details, not a decision about the person rights.';
} else if (failed > 0) {
  verdict = 'INCOMPLETE';
  note = failed + ' of ' + rows.length + ' systems did not answer. This is NOT a finding of no data. Re-run once those systems are reachable, and do not tell the requester you hold nothing.';
} else if (total > 0) {
  verdict = 'DATA_FOUND';
  note = total + ' record(s) found. All ' + answered + ' systems answered.';
} else {
  verdict = 'NO_DATA_FOUND';
  note = 'All ' + answered + ' systems answered and none held a matching record.';
}
return [{ json: {
  case_id: first.case_id || 'DSR-UNKNOWN',
  subject_hash: first.subject_hash || '',
  request_type: String(guard.request_type || 'Access'),
  received_at: now.toISOString(),
  due_at: due.toISOString(),
  verdict: verdict,
  systems_answered: answered,
  systems_failed: failed,
  records_found: total,
  note: note,
  entry: String(guard.entry || 'subworkflow'),
  findings: lines.join(' | ')
} }];

